arguments.command:
cd /app; cat migrations/0007* migrations/0008* migrations/0009* migrations/0010*; python3 - <<'E'
import glob
for f in glob.glob('seeds/*'):
    b=open(f,'rb').read()
    try: b.decode('utf-8'); print(f,'utf8 ok')
    except Exception as e: print(f,e)
    print(set(b.count(x) for x in [b'\r\n']), b[:3])
E
cut -d, -f8 seeds/specimens.csv|sort|uniq -c; cut -d, -f3 seeds/taxa.csv|sort|uniq -c

